package scp_candidate.Mining_Threat_Retreat_Supervisor

import org.sireum._
import art.Art
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Threat_Qualification_supervisor_tq_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq)
  }

  /** helper function to set the values of all input ports.
   * @param raw_threat payload for data port raw_threat
   * @param streak_state payload for data port streak_state
   */
  def put_concrete_inputs(raw_threat : Mining_Threat_Retreat_Supervisor.Raw_Threat_Observation,
                          streak_state : Mining_Threat_Retreat_Supervisor.Threat_State_Input): Unit = {
    put_raw_threat(raw_threat)
    put_streak_state(streak_state)
  }


  /** helper function to check Threat_Qualification_supervisor_tq's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param qualified_threat method that will be called with the value of the outgoing data
   *        port 'qualified_threat'.
   * @param threat_publication method that will be called with the value of the outgoing data
   *        port 'threat_publication'.
   * @param threat_invalidity method that will be called with the value of the outgoing data
   *        port 'threat_invalidity'.
   */
  def check_concrete_output(qualified_threat: Mining_Threat_Retreat_Supervisor.Qualified_Threat => B,
                            threat_publication: Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts => B,
                            threat_invalidity: Mining_Threat_Retreat_Supervisor.Threat_Invalidity => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val qualified_threatValue: Mining_Threat_Retreat_Supervisor.Qualified_Threat = get_qualified_threat().get
    if(!qualified_threat(qualified_threatValue)) {
      testFailures = testFailures :+ st"'qualified_threat' did not match expected: value of the outgoing data port is ${qualified_threatValue}"
    }
    val threat_publicationValue: Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts = get_threat_publication().get
    if(!threat_publication(threat_publicationValue)) {
      testFailures = testFailures :+ st"'threat_publication' did not match expected: value of the outgoing data port is ${threat_publicationValue}"
    }
    val threat_invalidityValue: Mining_Threat_Retreat_Supervisor.Threat_Invalidity = get_threat_invalidity().get
    if(!threat_invalidity(threat_invalidityValue)) {
      testFailures = testFailures :+ st"'threat_invalidity' did not match expected: value of the outgoing data port is ${threat_invalidityValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_raw_threat(value : Mining_Threat_Retreat_Supervisor.Raw_Threat_Observation): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq.operational_api.raw_threat_Id, Mining_Threat_Retreat_Supervisor.Raw_Threat_Observation_Payload(value))
  }

  // setter for in DataPort
  def put_streak_state(value : Mining_Threat_Retreat_Supervisor.Threat_State_Input): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq.operational_api.streak_state_Id, Mining_Threat_Retreat_Supervisor.Threat_State_Input_Payload(value))
  }

  // getter for out DataPort
  def get_qualified_threat(): Option[Mining_Threat_Retreat_Supervisor.Qualified_Threat] = {
    val value: Option[Mining_Threat_Retreat_Supervisor.Qualified_Threat] = get_qualified_threat_payload() match {
      case Some(Mining_Threat_Retreat_Supervisor.Qualified_Threat_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port qualified_threat.  Expecting 'Mining_Threat_Retreat_Supervisor.Qualified_Threat_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervisor.Qualified_Threat]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_qualified_threat_payload(): Option[Mining_Threat_Retreat_Supervisor.Qualified_Threat_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq.initialization_api.qualified_threat_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervisor.Qualified_Threat_Payload]]
  }

  // getter for out DataPort
  def get_threat_publication(): Option[Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts] = {
    val value: Option[Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts] = get_threat_publication_payload() match {
      case Some(Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port threat_publication.  Expecting 'Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_threat_publication_payload(): Option[Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq.initialization_api.threat_publication_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts_Payload]]
  }

  // getter for out DataPort
  def get_threat_invalidity(): Option[Mining_Threat_Retreat_Supervisor.Threat_Invalidity] = {
    val value: Option[Mining_Threat_Retreat_Supervisor.Threat_Invalidity] = get_threat_invalidity_payload() match {
      case Some(Mining_Threat_Retreat_Supervisor.Threat_Invalidity_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port threat_invalidity.  Expecting 'Mining_Threat_Retreat_Supervisor.Threat_Invalidity_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervisor.Threat_Invalidity]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_threat_invalidity_payload(): Option[Mining_Threat_Retreat_Supervisor.Threat_Invalidity_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq.initialization_api.threat_invalidity_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervisor.Threat_Invalidity_Payload]]
  }

}
